def match(orders):
    trades = []
    buy_book = []  # heap of (-price, arrival_time, id, qty)
    sell_book = []  # heap of (price, arrival_time, id, qty)
    order_map = {}  # id -> (side, price, qty, arrival_time)
    arrival_counter = 0

    def add_buy_to_book(order_id, price, qty, arrival_time):
        import heapq
        heapq.heappush(buy_book, (-price, arrival_time, order_id, qty))

    def add_sell_to_book(order_id, price, qty, arrival_time):
        import heapq
        heapq.heappush(sell_book, (price, arrival_time, order_id, qty))

    def match_buy(order_id, price, qty):
        import heapq
        while qty > 0 and sell_book:
            sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]
            if sell_price <= price:
                match_qty = min(qty, sell_qty)
                trades.append([order_id, sell_id, sell_price, match_qty])
                qty -= match_qty
                if sell_qty > match_qty:
                    heapq.heapreplace(sell_book, (sell_price, sell_arrival, sell_id, sell_qty - match_qty))
                else:
                    heapq.heappop(sell_book)
                    del order_map[sell_id]
            else:
                break
        return qty

    def match_sell(order_id, price, qty):
        import heapq
        while qty > 0 and buy_book:
            buy_price, buy_arrival, buy_id, buy_qty = buy_book[0]
            buy_price = -buy_price
            if buy_price >= price:
                match_qty = min(qty, buy_qty)
                trades.append([buy_id, order_id, buy_price, match_qty])
                qty -= match_qty
                if buy_qty > match_qty:
                    heapq.heapreplace(buy_book, (-buy_price, buy_arrival, buy_id, buy_qty - match_qty))
                else:
                    heapq.heappop(buy_book)
                    del order_map[buy_id]
            else:
                break
        return qty

    import heapq

    for order in orders:
        if order[0] == 'limit':
            cmd, order_id, side, price, qty = order
            if side == 'buy':
                remaining_qty = match_buy(order_id, price, qty)
                if remaining_qty > 0:
                    add_buy_to_book(order_id, price, remaining_qty, arrival_counter)
                    order_map[order_id] = ('buy', price, remaining_qty, arrival_counter)
            else:  # sell
                remaining_qty = match_sell(order_id, price, qty)
                if remaining_qty > 0:
                    add_sell_to_book(order_id, price, remaining_qty, arrival_counter)
                    order_map[order_id] = ('sell', price, remaining_qty, arrival_counter)
            arrival_counter += 1

        elif order[0] == 'ioc':
            cmd, order_id, side, price, qty = order
            if side == 'buy':
                match_buy(order_id, price, qty)
            else:  # sell
                match_sell(order_id, price, qty)
            arrival_counter += 1

        elif order[0] == 'market':
            cmd, order_id, side, qty = order
            if side == 'buy':
                match_buy(order_id, float('inf'), qty)
            else:  # sell
                match_sell(order_id, 0, qty)
            arrival_counter += 1

        elif order[0] == 'cancel':
            cmd, order_id = order
            if order_id in order_map:
                side, price, qty, arrival_time = order_map[order_id]
                del order_map[order_id]
                if side == 'buy':
                    buy_book = [(p, a, oid, q) for p, a, oid, q in buy_book if oid != order_id]
                    heapq.heapify(buy_book)
                else:  # sell
                    sell_book = [(p, a, oid, q) for p, a, oid, q in sell_book if oid != order_id]
                    heapq.heapify(sell_book)
            arrival_counter += 1

    return trades

